def canon(cells):
    best=None
    pts=[(r,c) for r,c in cells]
    for tf in range(8):
        pts2=[]
        for r,c in pts:
            if tf==0: p=(r,c)
            elif tf==1: p=(r,-c)
            elif tf==2: p=(-r,c)
            elif tf==3: p=(-r,-c)
            elif tf==4: p=(c,r)
            elif tf==5: p=(c,-r)
            elif tf==6: p=(-c,r)
            else: p=(-c,-r)
            pts2.append(p)
        mr=min(p[0] for p in pts2); mc=min(p[1] for p in pts2)
        s=tuple(sorted((r-mr,c-mc) for r,c in pts2))
        if best is None or s<best: best=s
    return best

